<?php
namespace App\Http\Controllers; use App\Models\KategoriBantuan; use Illuminate\Http\Request;
class KategoriController extends Controller {public function index(){ $items=KategoriBantuan::withCount('jenis')->paginate(10);return view('admin.kategori.index',compact('items'));} public function create(){return view('admin.kategori.form',['item'=>new KategoriBantuan]);} public function store(Request $r){KategoriBantuan::create($r->validate(['nama'=>'required|string|max:50|unique:kategori_bantuan,nama','deskripsi'=>'nullable|string']));return redirect()->route('admin.kategori.index')->with('success','Kategori ditambahkan.');} public function edit(KategoriBantuan $kategori){return view('admin.kategori.form',['item'=>$kategori]);} public function update(Request $r,KategoriBantuan $kategori){$kategori->update($r->validate(['nama'=>'required|string|max:50|unique:kategori_bantuan,nama,'.$kategori->id_kategori.',id_kategori','deskripsi'=>'nullable|string']));return redirect()->route('admin.kategori.index')->with('success','Kategori diperbarui.');} public function destroy(KategoriBantuan $kategori){if($kategori->jenis()->exists())return back()->withErrors(['delete'=>'Kategori masih memiliki jenis bantuan.']);$kategori->delete();return back()->with('success','Kategori dihapus.');}}
